<script setup lang="ts">import type{Plane}from'../types/protocol';import ControlRenderer from'./ControlRenderer.vue';defineProps<{plane:Plane}>();defineEmits<{set:[string,number];toggle:[string,number];fire:[string]}>()</script><template><section class="plane"><header><h2>{{plane.label}}</h2><small>{{plane.id}}</small></header><div class="plane-grid"><article v-for="control in plane.controls" :key="control.id"><ControlRenderer :control="control" @set="$emit('set',control.id,$event)" @toggle="$emit('toggle',control.id,$event)" @fire="$emit('fire',control.id)"/></article></div></section></template>
